class Solution {
public:
    int getSum(vector<int>& nums) {
        const long long MOD=1000000007;
        long long ans=0;
        for (int d : {1,-1}) {
            long long runSum=0, runCount=0;
            for (int i=0;i<(int)nums.size();++i) {
                if (i>0 && nums[i]-nums[i-1]==d) {
                    runSum=(runSum+runCount*nums[i]+nums[i])%MOD;
                    ++runCount;
                } else {runSum=nums[i];runCount=1;}
                ans=(ans+runSum)%MOD;
            }
        }
        for (int x:nums) ans=(ans-x+MOD)%MOD;
        return (int)ans;
    }
};
